function countPrimes(n) {
  if (n < 3) {
    return 0;
  }
  const composite = new Uint8Array(n);
  let count = 0;
  for (let i = 2; i < n; i++) {
    if (composite[i] === 1) {
      continue;
    }
    count++;
    for (let multiple = i * i; multiple < n; multiple += i) {
      composite[multiple] = 1;
    }
  }
  return count;
}

